def s3url(cdstar_url):
    comps = cdstar_url.split('/')
    key = (comps[-2], comps[-1])
    if key in MAPPING:
        return f"https://s3.nexus.mpcdf.mpg.de/eva-dlce-tsammalex/{MAPPING[key]}"
